<?php
$tab=$query['tab']??'departments';if(!isset($tables[$tab]))$tab='departments';
echo '<div class="pill-tabs">';foreach($tables as $k=>$meta)echo '<a class="'.($tab===$k?'active':'').'" href="?page=master_data&tab='.$k.'">'.e($meta[0]).'</a>';echo '</div>';
$edit=null;if(isset($query['edit'])){$s=$db->prepare("SELECT * FROM $tab WHERE id=?");$s->execute([(int)$query['edit']]);$edit=$s->fetch();}$rows=$db->query("SELECT * FROM $tab ORDER BY name")->fetchAll();
echo '<div class="grid two"><div class="table-wrap"><table><thead><tr><th>Name</th>'.($tables[$tab][2]?'<th>Code</th>':'').'<th>Status</th><th></th></tr></thead><tbody>';foreach($rows as $r){echo '<tr><td>'.e($r['name']).'</td>'.($tables[$tab][2]?'<td>'.e($r['code']).'</td>':'').'<td>'.badge($r['status'],$r['status']==='active'?'good':'neutral').'</td><td><a class="btn btn-secondary" href="?page=master_data&tab='.$tab.'&edit='.$r['id'].'">Edit</a></td></tr>';}echo '</tbody></table></div><div class="form-card"><h3>'.($edit?'Edit ':'Add ').e($tables[$tab][0]).'</h3><form method="post">'.csrf_field().'<input type="hidden" name="table" value="'.e($tab).'"><input type="hidden" name="id" value="'.e($edit['id']??'').'"><div class="form-group"><label>Name</label><input name="name" required value="'.e($edit['name']??'').'"></div>';if($tables[$tab][2])echo '<div class="form-group" style="margin-top:10px"><label>Code</label><input name="code" value="'.e($edit['code']??'').'"></div>';echo '<div class="form-group" style="margin-top:10px"><label>Status</label><select name="status"><option'.selected($edit['status']??'active','active').'>active</option><option'.selected($edit['status']??'','inactive').'>inactive</option></select></div><button class="btn btn-primary" style="margin-top:12px">Save</button></form></div></div>';

